export type SequenceNumber = number;

/**
 * Opaque pagination cursor (docs/API.md section 6). It is base64url text without padding;
 * its contents are the server's business and a client MUST NOT parse, construct or modify
 * one.
 */
export type Cursor = string;

/**
 * Human-friendly alias, unique inside its parent. Mutable, and never a substitute for the
 * identifier (docs/DOMAIN_MODEL.md section 3).
 */
export type Slug = string;

/**
 * Name a human reads. It is description and never an authorisation input.
 */
export type DisplayName = string;

/**
 * Address a human is known by. It is an alias for a user, never an identity: the
 * identifier is what every other record references. The bound is the RFC 5321 maximum path
 * length. The pattern is deliberately permissive — one at-sign, no whitespace and no
 * control characters — because a stricter one rejects addresses that work: a dotless host
 * such as administrator@localhost is what a fresh self-hosted installation is seeded with,
 * and deliverability is not something a schema can decide.
 */
export type EmailAddress = string;

/**
 * Git branch name. Bounded and restricted to the characters a ref may hold, so a value
 * stored here cannot become an argument to something else.
 */
export type GitRefName = string;

/**
 * The canonical member of a repository identity on its own, for the records that store the
 * normalised form without the clone URLs beside it (docs/DOMAIN_MODEL.md section 9). Its
 * shape is repository_identity.canonical, and the shared normaliser in packages/protocol
 * produces both, so a workspace and a project cannot disagree about what one repository
 * is.
 */
export type RepositoryCanonical = string;

/**
 * Operator-assigned environment label. Its shape is the connector protocol's
 * environment_label, because an enrolment token pins the labels a registering environment
 * must declare (docs/CONNECTOR_PROTOCOL.md section 4.1).
 */
export type EnvironmentLabel = string;

/**
 * Operating system an environment runs, as the connector reported it.
 */
export type PlatformName = string;

/**
 * CPU architecture an environment runs, as the connector reported it.
 */
export type ArchitectureName = string;

/**
 * Capability a connector build advertises, such as http-tunnel, websocket-tunnel,
 * git-context or local-mcp-bridge. Unknown values are accepted so that a newer connector
 * is classified by docs/CONNECTOR_PROTOCOL.md section 19 rather than rejected outright.
 */
export type ConnectorCapability = string;

/**
 * Connector release version, for example 0.1.0. Its shape is the connector protocol's
 * semantic_version.
 */
export type ConnectorVersion = string;

/**
 * sha256:<hex> digest of the DER form of an issued connector certificate (ADR-0014). It is
 * unique across connectors and is how a verified peer certificate is resolved to a
 * connector record.
 */
export type CertificateFingerprint = string;

/**
 * A lower bound, in seconds, on how long a connector had been silent when a conclusion was
 * drawn about it.
 */
export type SilenceSeconds = number;

/**
 * Stable sha256:<hex> digest of a workspace's absolute path on the development machine.
 * The control plane stores the digest rather than the path, because a display label and a
 * stable local hash are sufficient to recognise the same checkout again
 * (docs/DOMAIN_MODEL.md section 9).
 */
export type PathHash = string;

/**
 * Human-readable workspace label, which is the checkout directory's own name and never its
 * full path. Path separators and control characters are refused, so a full path cannot be
 * smuggled through it.
 */
export type WorkspaceDisplayLabel = string;

/**
 * A commit identifier, lowercase hexadecimal. Bounded so that an abbreviated and a full
 * identifier are both accepted and nothing else is.
 */
export type GitCommit = string;

/**
 * Provider-agnostic repository identity (docs/DOMAIN_MODEL.md section 6). canonical is the
 * normalised host-and-path form that two clone URLs for the same repository both reduce
 * to, which is what lets an SSH remote and an HTTPS remote be recognised as one
 * repository. clone_urls records the forms actually seen, for display and for a connector
 * to match a checkout against.
 */
export interface RepositoryIdentity {
  /**
   * Normalised host and path, lowercase host, no scheme, no credentials, no .git suffix
   * and no trailing slash, for example github.com/example/refresh-surplus.
   */
  readonly canonical: string;
  /**
   * Clone URLs that reduce to canonical, in the order they were supplied. Duplicates are
   * removed by the control plane before storage.
   */
  readonly clone_urls?: readonly string[];
}

/**
 * A viewport the project validates at (docs/UX_FLOWS.md section 4). The bounds are the
 * browser protocol's, because a viewport stored here is one a browser session is later
 * asked to adopt; a value the worker would refuse must not be storable.
 */
export interface ValidationViewport {
  /**
   * Viewport width in CSS pixels.
   */
  readonly width: number;
  /**
   * Viewport height in CSS pixels.
   */
  readonly height: number;
  /**
   * Device pixel ratio. Absent means 1, which is what a browser session adopts when the
   * project does not say otherwise.
   */
  readonly device_scale_factor?: number;
}

/**
 * Project settings (docs/DOMAIN_MODEL.md section 6). Stage 1 holds the default validation
 * viewports and nothing else; the object refuses unknown members so a setting cannot be
 * introduced in one service without being defined here first.
 */
export interface ProjectSettings {
  /**
   * Viewports a finding is expected to be validated at. It defaults to 390x844 and
   * 1440x900, which AGENTS.md requires of browser-facing work and the Stage 1 completion
   * gate checks against.
   */
  readonly default_validation_viewports: readonly ValidationViewport[];
}

/**
 * The top-level administrative and data-isolation boundary (docs/DOMAIN_MODEL.md section
 * 4).
 */
export interface Organisation {
  /**
   * Organisation identity, conventionally prefixed org_.
   */
  readonly id: Identifier;
  /**
   * Display name.
   */
  readonly name: DisplayName;
  /**
   * Mutable alias.
   */
  readonly slug: Slug;
  /**
   * Lifecycle status.
   */
  readonly status: OrganisationStatus;
  /**
   * When the organisation was created.
   */
  readonly created_at: Timestamp;
  /**
   * When it last changed.
   */
  readonly updated_at: Timestamp;
}

/**
 * A human identity (docs/DOMAIN_MODEL.md section 5). It never carries credential material:
 * whether a password exists is stated, and the hash is not part of any representation that
 * leaves the database.
 */
export interface User {
  /**
   * User identity, conventionally prefixed usr_.
   */
  readonly id: Identifier;
  /**
   * Owning organisation, carried for defence-in-depth filtering (docs/DOMAIN_MODEL.md
   * section 3).
   */
  readonly organisation_id: Identifier;
  /**
   * Address the human is known by.
   */
  readonly email: EmailAddress;
  /**
   * Name shown in a timeline.
   */
  readonly display_name: DisplayName;
  /**
   * Lifecycle status.
   */
  readonly status: UserStatus;
  /**
   * Whether this user can authenticate locally. It is the fact a first-run screen needs,
   * and it says nothing about the credential itself. The name avoids the word the schema
   * checker forbids in a field, which exists so that no protocol field can ever carry a
   * credential.
   */
  readonly local_credential_set?: boolean;
  /**
   * When the user record was created.
   */
  readonly created_at: Timestamp;
  /**
   * When it last changed.
   */
  readonly updated_at: Timestamp;
}

/**
 * The principal working boundary (docs/DOMAIN_MODEL.md section 6). A review belongs to
 * exactly one project, and a browser session may only route to services authorised for the
 * same project.
 */
export interface Project {
  /**
   * Project identity, conventionally prefixed prj_.
   */
  readonly id: Identifier;
  /**
   * Owning organisation, carried for defence-in-depth filtering.
   */
  readonly organisation_id: Identifier;
  /**
   * Display name.
   */
  readonly name: DisplayName;
  /**
   * Alias, unique within the organisation.
   */
  readonly slug: Slug;
  /**
   * Repository the project's work lands in. Absent until an operator supplies one; a
   * change to it is audited as project.repository_changed.
   */
  readonly repository_identity?: RepositoryIdentity;
  /**
   * Branch reviews are captured against by default.
   */
  readonly default_branch: GitRefName;
  /**
   * Lifecycle status. Deleting a project archives it.
   */
  readonly status: ProjectStatus;
  /**
   * Project settings.
   */
  readonly settings: ProjectSettings;
  /**
   * Optimistic-concurrency version (docs/API.md section 5.2). A write carrying a different
   * expected_version is refused with VERSION_CONFLICT rather than silently overwriting.
   */
  readonly version: number;
  /**
   * When the project was created.
   */
  readonly created_at: Timestamp;
  /**
   * When it last changed.
   */
  readonly updated_at: Timestamp;
}

/**
 * What a human session tells its own holder (docs/API.md section 4). The session token
 * lives in an HTTP-only cookie and is never part of this representation; project_ids
 * absent means organisation-wide scope, and a list means exactly those projects.
 */
export interface HumanSession {
  /**
   * Session identity, conventionally prefixed vwr_.
   */
  readonly session_id: Identifier;
  /**
   * The authenticated user. Absent for a session issued from the bootstrap administrator
   * token, which has no user record behind it (ADR-0016).
   */
  readonly user_id?: Identifier;
  /**
   * Organisation the session acts in.
   */
  readonly organisation_id?: Identifier;
  /**
   * Address of the authenticated user, when there is one.
   */
  readonly email?: EmailAddress;
  /**
   * Name shown in the application shell.
   */
  readonly display: DisplayName;
  /**
   * Projects the session may reach. Absent means every project in the organisation.
   */
  readonly project_ids?: readonly Identifier[];
  /**
   * When the session stops being usable without revocation.
   */
  readonly expires_at: Timestamp;
}

/**
 * A bounded agent execution context (docs/DOMAIN_MODEL.md section 11), as a human
 * interface shows it. project_id is required because an agent session is bound to exactly
 * one project and a half-resolved one is not representable (ADR-0020). capabilities is
 * what the session was granted when it opened and not what its credential carries now, so
 * a record of what an agent was allowed to do survives a later revocation. No member of
 * this shape can carry a credential: the token is never part of a session representation.
 */
export interface AgentSession {
  /**
   * Agent-session identity, conventionally prefixed ags_.
   */
  readonly id: Identifier;
  /**
   * Owning organisation.
   */
  readonly organisation_id?: Identifier;
  /**
   * Project the session is bound to. Exactly one, always.
   */
  readonly project_id: Identifier;
  /**
   * Connector the session reached the control plane through, where it came through the
   * local bridge.
   */
  readonly connector_id?: Identifier;
  /**
   * Workspace the session resolved, where the project has one.
   */
  readonly workspace_id?: Identifier;
  /**
   * Client's self-reported name. It is description and never an authorisation input: the
   * credential decides what the session may do.
   */
  readonly agent_type: DisplayName;
  /**
   * Client's self-reported version.
   */
  readonly agent_version?: DisplayName;
  /**
   * Capabilities the session holds. It cannot exceed the set its credential carried when
   * it opened.
   */
  readonly capabilities: readonly AgentCapability[];
  /**
   * Branch the workspace was on when the session started.
   */
  readonly branch?: GitRefName;
  /**
   * Head commit at that moment.
   */
  readonly head_commit?: GitCommit;
  /**
   * Session status.
   */
  readonly status: AgentSessionStatus;
  /**
   * When the session opened.
   */
  readonly started_at: Timestamp;
  /**
   * When the control plane last handled a request from it.
   */
  readonly last_seen_at?: Timestamp;
  /**
   * When it ended, where it has.
   */
  readonly ended_at?: Timestamp;
}

/**
 * A registered development location such as a VM or workstation (docs/DOMAIN_MODEL.md
 * section 7). An environment may host several workspaces, but every published service and
 * session association is explicitly project scoped, so project_id is a default rather than
 * the whole of the authorisation.
 */
export interface Environment {
  /**
   * Environment identity, conventionally prefixed env_.
   */
  readonly id: Identifier;
  /**
   * Owning organisation, carried for defence-in-depth filtering.
   */
  readonly organisation_id: Identifier;
  /**
   * Project the environment was enrolled for. Absent when the enrolment token was
   * organisation scoped.
   */
  readonly project_id?: Identifier;
  /**
   * Operator-visible environment name, as the connector reported it. It is description and
   * never an authorisation input.
   */
  readonly name: DisplayName;
  /**
   * Operating system the environment runs.
   */
  readonly platform: PlatformName;
  /**
   * CPU architecture the environment runs.
   */
  readonly architecture: ArchitectureName;
  /**
   * Operator-assigned labels. An enrolment token may pin the labels a registering
   * environment must declare.
   */
  readonly labels: readonly EnvironmentLabel[];
  /**
   * Trust level. Stage 1 has one.
   */
  readonly trust_level: EnvironmentTrustLevel;
  /**
   * Lifecycle status.
   */
  readonly status: EnvironmentStatus;
  /**
   * When a connector for this environment was last heard from. Absent until one has been.
   */
  readonly last_seen_at?: Timestamp;
  /**
   * When the environment was registered.
   */
  readonly created_at: Timestamp;
}

/**
 * A connector installation and its cryptographic identity (docs/DOMAIN_MODEL.md section
 * 8). The device private key is generated on the development machine and never leaves it,
 * so this record has no member capable of carrying one: it holds the certificate
 * fingerprint the control plane resolves a verified peer certificate by, and nothing
 * secret.
 */
export interface Connector {
  /**
   * Connector identity, conventionally prefixed con_.
   */
  readonly id: Identifier;
  /**
   * Owning organisation, carried for defence-in-depth filtering.
   */
  readonly organisation_id: Identifier;
  /**
   * Environment this connector runs in.
   */
  readonly environment_id: Identifier;
  /**
   * Project the connector was enrolled for. Absent when the enrolment token was
   * organisation scoped.
   */
  readonly project_id?: Identifier;
  /**
   * Fingerprint of the issued client certificate, unique across connectors.
   */
  readonly certificate_fingerprint: CertificateFingerprint;
  /**
   * When the issued identity expires. Identities are bounded in time.
   */
  readonly certificate_not_after: Timestamp;
  /**
   * Connector release the environment runs.
   */
  readonly version: ConnectorVersion;
  /**
   * Capabilities the connector build advertises.
   */
  readonly capabilities: readonly ConnectorCapability[];
  /**
   * Lifecycle status.
   */
  readonly status: ConnectorStatus;
  /**
   * When the connector most recently reached ACTIVE. Absent before its first channel.
   */
  readonly connected_at?: Timestamp;
  /**
   * When the last heartbeat arrived. Absent before the first one.
   */
  readonly last_heartbeat_at?: Timestamp;
  /**
   * When the identity was revoked. Absent unless the connector is REVOKED.
   */
  readonly revoked_at?: Timestamp;
  /**
   * When the identity was issued.
   */
  readonly created_at: Timestamp;
}

/**
 * A repository checkout a connector reports or an operator registers (docs/DOMAIN_MODEL.md
 * section 9). It holds a stable path hash and a display label rather than the checkout's
 * full path, and it has no member capable of carrying source file contents or a
 * changed-path list: what is reportable about somebody else's machine is bounded by this
 * schema rather than by the code that fills it in.
 */
export interface Workspace {
  /**
   * Workspace identity, conventionally prefixed wsp_.
   */
  readonly id: Identifier;
  /**
   * Owning organisation, carried for defence-in-depth filtering.
   */
  readonly organisation_id: Identifier;
  /**
   * Project the checkout belongs to.
   */
  readonly project_id: Identifier;
  /**
   * Environment holding the checkout. Absent for a workspace registered administratively
   * rather than observed by a connector.
   */
  readonly environment_id?: Identifier;
  /**
   * Connector that last reported the checkout. Absent for an administratively registered
   * workspace.
   */
  readonly connector_id?: Identifier;
  /**
   * Stable digest of the checkout's absolute path.
   */
  readonly path_hash: PathHash;
  /**
   * Label a human reads, which is the checkout directory's own name.
   */
  readonly display_path: WorkspaceDisplayLabel;
  /**
   * Canonical identity of the checkout's remote. Absent when the checkout has no remote
   * that could be normalised; an absent value is reported as absent rather than guessed
   * at.
   */
  readonly repository_identity?: RepositoryCanonical;
  /**
   * Checked-out branch.
   */
  readonly branch: GitRefName;
  /**
   * HEAD commit.
   */
  readonly head_commit: GitCommit;
  /**
   * Whether the working tree has uncommitted changes. Which files changed is deliberately
   * not recorded.
   */
  readonly dirty: boolean;
  /**
   * How the workspace came to be known.
   */
  readonly source: WorkspaceObservationSource;
  /**
   * When the control plane last received this state. Absent until a first observation.
   */
  readonly last_observed_at?: Timestamp;
  /**
   * When the workspace record was created.
   */
  readonly created_at: Timestamp;
}

/**
 * The principal an event is attributed to (docs/EVENTS.md section 2).
 */
export interface Actor {
  /**
   * Principal kind. It is the authoritative part of an actor; display is not.
   */
  readonly type: ActorType;
  /**
   * Identifier of the principal, absent for a system actor that has none.
   */
  readonly id?: Identifier;
  /**
   * Human-readable label for a timeline. It is description and never an authorisation
   * input.
   */
  readonly display?: string;
}

/**
 * Correlation identifiers (docs/EVENTS.md section 2, docs/ARCHITECTURE.md section 15).
 * Every member is an opaque identifier: correlation never carries a header, a body or a
 * secret.
 */
export interface Correlation {
  /**
   * The API request that caused the event, conventionally prefixed req_.
   */
  readonly request_id?: Identifier;
  /**
   * The event that caused this one, conventionally prefixed evt_.
   */
  readonly causation_event_id?: Identifier;
  /**
   * Connector, conventionally prefixed con_.
   */
  readonly connector_id?: Identifier;
  /**
   * Environment, conventionally prefixed env_.
   */
  readonly environment_id?: Identifier;
  /**
   * Workspace, conventionally prefixed wsp_.
   */
  readonly workspace_id?: Identifier;
  /**
   * Published service, conventionally prefixed svc_.
   */
  readonly published_service_id?: Identifier;
  /**
   * Agent session, conventionally prefixed ags_.
   */
  readonly agent_session_id?: Identifier;
  /**
   * Browser session, conventionally prefixed brs_.
   */
  readonly browser_session_id?: Identifier;
  /**
   * Browser worker, conventionally prefixed wkr_.
   */
  readonly worker_id?: Identifier;
  /**
   * Artefact, conventionally prefixed art_.
   */
  readonly artefact_id?: Identifier;
  /**
   * Review, conventionally prefixed rev_.
   */
  readonly review_id?: Identifier;
  /**
   * Finding, conventionally prefixed fin_.
   */
  readonly finding_id?: Identifier;
  /**
   * Annotation, conventionally prefixed ann_.
   */
  readonly annotation_id?: Identifier;
  /**
   * Durable job, conventionally prefixed job_.
   */
  readonly job_id?: Identifier;
}

/**
 * The docs/EVENTS.md section 2 event envelope. Every event names the organisation it
 * belongs to, its position in a stream, and the actor that caused it; the payload schema
 * is selected by type. project_id is optional because an occurrence can precede any
 * project association — a connector enrolment does — and every project-scoped read filters
 * on it.
 */
export interface Envelope {
  /**
   * Event identifier, conventionally prefixed evt_. Consumers deduplicate on it.
   */
  readonly id: Identifier;
  /**
   * Envelope schema version. Stage 1 accepts 1 only; any other value is rejected rather
   * than best-effort parsed.
   */
  readonly schema_version: number;
  /**
   * Monotonic position within the stream.
   */
  readonly sequence: SequenceNumber;
  /**
   * Event type. This codec owns the types in message_type; an event of another type is
   * decoded by the schema source that owns it.
   */
  readonly type: MessageType;
  /**
   * When the occurrence happened.
   */
  readonly occurred_at: Timestamp;
  /**
   * When the control plane committed the record.
   */
  readonly recorded_at: Timestamp;
  /**
   * Owning organisation, conventionally prefixed org_.
   */
  readonly organisation_id: Identifier;
  /**
   * Owning project, conventionally prefixed prj_. Every project-scoped read of this stream
   * filters on it.
   */
  readonly project_id?: Identifier;
  /**
   * Principal the occurrence is attributed to.
   */
  readonly actor: Actor;
  /**
   * Correlation identifiers.
   */
  readonly correlation?: Correlation;
}

/**
 * Payload of organisation.created.
 */
export interface OrganisationCreatedPayload {
  /**
   * Mutable human-friendly alias. The identifier is authoritative; this is not.
   */
  readonly slug: string;
  /**
   * Display name.
   */
  readonly name: string;
}

/**
 * Payload of project.created.
 */
export interface ProjectCreatedPayload {
  /**
   * Project-scoped alias. Mutable, and never a substitute for the identifier.
   */
  readonly slug: string;
  /**
   * Display name.
   */
  readonly name: string;
  /**
   * Branch the project captures reviews against. Absent on a project created before the
   * field existed.
   */
  readonly default_branch?: GitRefName;
  /**
   * Normalised repository identity the project was created with, when one was supplied.
   * The canonical form alone: the clone URLs are queryable on the record and add nothing
   * an auditor needs.
   */
  readonly repository_canonical?: string;
}

/**
 * Payload of project.repository_changed. It carries both sides of the move, because a
 * review captured before it was interpreted against the previous repository
 * (docs/DOMAIN_MODEL.md section 6).
 */
export interface ProjectRepositoryChangedPayload {
  /**
   * Normalised identity before the change. Absent when the project had no repository
   * association.
   */
  readonly previous_canonical?: string;
  /**
   * Normalised identity after the change.
   */
  readonly new_canonical: string;
}

/**
 * Payload of user.invited. Issuing a credential-establishing token is a permission change,
 * and docs/SECURITY.md section 16 requires an audit record for one. It never carries the
 * token: a reader learns that a way in exists and when it closes, not what it is.
 */
export interface UserInvitedPayload {
  /**
   * User the token establishes credentials for.
   */
  readonly user_id: Identifier;
  /**
   * Kind of token that was issued.
   */
  readonly method: LoginMethod;
  /**
   * When the token stops being usable, whether or not it was used.
   */
  readonly expires_at: Timestamp;
}

/**
 * Payload of user.credentials_set. Setting a password is a permission change and
 * docs/SECURITY.md section 16 requires an audit record for one; the record names the user
 * and the route the credential arrived by, and nothing else.
 */
export interface UserCredentialsSetPayload {
  /**
   * User whose password changed.
   */
  readonly user_id: Identifier;
  /**
   * How the credential was established.
   */
  readonly method: LoginMethod;
}

/**
 * Payload of authentication.login_succeeded.
 */
export interface AuthenticationLoginSucceededPayload {
  /**
   * Session that was issued.
   */
  readonly session_id: Identifier;
  /**
   * User that authenticated. Absent for the bootstrap-token exchange, which has no user
   * record behind it.
   */
  readonly user_id?: Identifier;
  /**
   * How the human authenticated.
   */
  readonly method: LoginMethod;
}

/**
 * Payload of authentication.login_failed. It never carries the submitted credential, and
 * never the identifier that was typed beside it: a password mistyped into an email field
 * would otherwise be written to an append-only table (docs/SECURITY.md section 18).
 */
export interface AuthenticationLoginFailedPayload {
  /**
   * Stable failure class.
   */
  readonly reason: LoginFailureReason;
  /**
   * Route the attempt arrived by.
   */
  readonly method: LoginMethod;
  /**
   * User the attempt named, when it named one that exists. Absent for an unknown address,
   * which is what stops the audit trail confirming which addresses have accounts.
   */
  readonly user_id?: Identifier;
}

/**
 * Payload of session.revoked.
 */
export interface SessionRevokedPayload {
  /**
   * Session that was revoked.
   */
  readonly session_id: Identifier;
  /**
   * User the session belonged to, when it belonged to one.
   */
  readonly user_id?: Identifier;
  /**
   * Why it was revoked.
   */
  readonly reason: SessionRevocationReason;
}

/**
 * Payload of project.updated. It names the fields that changed rather than restating the
 * record: current state is queryable, and the audit question is what moved.
 */
export interface ProjectUpdatedPayload {
  /**
   * Attribute names that changed, in schema order.
   */
  readonly changed_fields: readonly string[];
}

/**
 * Payload of project.archived. It carries previous and new state, which docs/EVENTS.md
 * section 8 requires of a state change.
 */
export interface ProjectArchivedPayload {
  /**
   * Status before the change.
   */
  readonly previous_status: ProjectStatus;
  /**
   * Status after the change.
   */
  readonly new_status: ProjectStatus;
}

/**
 * Payload of connector.enrolled. It records the identity that was issued and the
 * environment it was issued to, and it never carries the enrolment token that was
 * redeemed: an event is append-only, so a credential written into one cannot be taken out
 * again (docs/EVENTS.md section 8).
 */
export interface ConnectorEnrolledPayload {
  /**
   * Environment the identity was issued to.
   */
  readonly environment_id: Identifier;
  /**
   * Name the environment reported for itself. Description, never an authorisation input.
   */
  readonly environment_name: DisplayName;
  /**
   * Operating system the environment reported.
   */
  readonly platform: PlatformName;
  /**
   * CPU architecture the environment reported.
   */
  readonly architecture: ArchitectureName;
  /**
   * Connector release that enrolled.
   */
  readonly connector_version: ConnectorVersion;
  /**
   * Capabilities the connector build advertised.
   */
  readonly capabilities: readonly ConnectorCapability[];
  /**
   * Fingerprint of the certificate that was issued.
   */
  readonly certificate_fingerprint: CertificateFingerprint;
  /**
   * When the issued identity expires.
   */
  readonly identity_expires_at: Timestamp;
  /**
   * Identifier of the token that was redeemed. The identifier, never the token.
   */
  readonly enrolment_token_id?: Identifier;
  /**
   * Status the record entered, which is PENDING_ENROLMENT until the first authenticated
   * channel.
   */
  readonly new_status: ConnectorStatus;
}

/**
 * Payload of connector.connected. Both sides of the transition are named, so the audit
 * trail states what moved rather than only where it landed, and the trigger is a closed
 * vocabulary so no free text is needed.
 */
export interface ConnectorConnectedPayload {
  /**
   * Status before the transition.
   */
  readonly previous_status: ConnectorStatus;
  /**
   * Status after it, which is ACTIVE.
   */
  readonly new_status: ConnectorStatus;
  /**
   * Whether a channel was established or a heartbeat arrived from a degraded state.
   */
  readonly trigger: ConnectorConnectedTrigger;
}

/**
 * Payload of connector.degraded. Degradation is a conclusion drawn from silence, so the
 * payload states how long the silence had lasted rather than what the connector said about
 * itself.
 */
export interface ConnectorDegradedPayload {
  /**
   * Status before the transition.
   */
  readonly previous_status: ConnectorStatus;
  /**
   * Status after it, which is DEGRADED.
   */
  readonly new_status: ConnectorStatus;
  /**
   * What caused it. Degradation has one cause: missed heartbeats.
   */
  readonly trigger: ConnectorDegradedTrigger;
  /**
   * Lower bound on the silence, because the sweep observes silence rather than measuring
   * it.
   */
  readonly silent_for_seconds_at_least: SilenceSeconds;
}

/**
 * Payload of connector.disconnected. A closed channel and an exhausted heartbeat budget
 * are different observations and are distinguished by trigger, so an operator can tell a
 * clean stop from a network that went away.
 */
export interface ConnectorDisconnectedPayload {
  /**
   * Status before the transition.
   */
  readonly previous_status: ConnectorStatus;
  /**
   * Status after it, which is DISCONNECTED.
   */
  readonly new_status: ConnectorStatus;
  /**
   * Whether the channel closed or the disconnect threshold was exceeded.
   */
  readonly trigger: ConnectorDisconnectedTrigger;
  /**
   * Lower bound on the silence. Present only for heartbeat_timeout: a closed channel is
   * observed rather than inferred.
   */
  readonly silent_for_seconds_at_least?: SilenceSeconds;
}

/**
 * Payload of connector.revoked. It records what revocation reached, because
 * docs/CONNECTOR_PROTOCOL.md section 18 makes revocation six things at once and an auditor
 * needs to see that all six happened.
 */
export interface ConnectorRevokedPayload {
  /**
   * Status before revocation.
   */
  readonly previous_status: ConnectorStatus;
  /**
   * Status after it, which is REVOKED.
   */
  readonly new_status: ConnectorStatus;
  /**
   * How many published services the revocation closed.
   */
  readonly routes_revoked: number;
  /**
   * How many browser sessions were marked disconnected by it.
   */
  readonly sessions_disconnected: number;
  /**
   * How many live connector channels were closed. Zero when the connector held none.
   */
  readonly channels_closed?: number;
  /**
   * How many live agent credentials the connector had minted were revoked with it
   * (ADR-0023). Refusing the exchange closes only the next one, so this count is what
   * closed the ones already issued. Each also writes its own session.revoked with the
   * reason connector_revoked.
   */
  readonly agent_credentials_revoked?: number;
}

/**
 * Payload of workspace.observed. It carries exactly what docs/CONNECTOR_PROTOCOL.md
 * section 9 permits a connector to report about a checkout, and has no member capable of
 * carrying file contents, a changed-path list or a full filesystem path.
 */
export interface WorkspaceObservedPayload {
  /**
   * Workspace that was observed.
   */
  readonly workspace_id: Identifier;
  /**
   * Environment holding it. Absent for an administratively registered workspace.
   */
  readonly environment_id?: Identifier;
  /**
   * Stable digest of the checkout's absolute path.
   */
  readonly path_hash: PathHash;
  /**
   * The checkout directory's own name.
   */
  readonly display_path: WorkspaceDisplayLabel;
  /**
   * Canonical identity of the checkout's remote, when it has one that could be normalised.
   */
  readonly repository_identity?: RepositoryCanonical;
  /**
   * Checked-out branch.
   */
  readonly branch: GitRefName;
  /**
   * HEAD commit.
   */
  readonly head_commit: GitCommit;
  /**
   * Whether the working tree had uncommitted changes.
   */
  readonly dirty: boolean;
  /**
   * How the workspace came to be known.
   */
  readonly source: WorkspaceObservationSource;
}

/**
 * Payload of workspace.head_changed. It carries both sides of the move, because a review
 * captured before it was captured against the previous head and an auditor reading only
 * the new one could not tell.
 */
export interface WorkspaceHeadChangedPayload {
  /**
   * Workspace whose head moved.
   */
  readonly workspace_id: Identifier;
  /**
   * Environment holding it, when a connector reported the change.
   */
  readonly environment_id?: Identifier;
  /**
   * Branch before the change.
   */
  readonly previous_branch: GitRefName;
  /**
   * HEAD commit before it.
   */
  readonly previous_head_commit: GitCommit;
  /**
   * Dirty state before it.
   */
  readonly previous_dirty: boolean;
  /**
   * Branch after it.
   */
  readonly branch: GitRefName;
  /**
   * HEAD commit after it.
   */
  readonly head_commit: GitCommit;
  /**
   * Dirty state after it.
   */
  readonly dirty: boolean;
}

/**
 * Payload of job.enqueued.
 */
export interface JobEnqueuedPayload {
  /**
   * Job identity, conventionally prefixed job_.
   */
  readonly job_id: Identifier;
  /**
   * Work the job performs.
   */
  readonly kind: JobKind;
  /**
   * Earliest time the runner may claim it.
   */
  readonly run_after: Timestamp;
}

/**
 * Payload of job.succeeded.
 */
export interface JobSucceededPayload {
  /**
   * Job identity.
   */
  readonly job_id: Identifier;
  /**
   * Work the job performed.
   */
  readonly kind: JobKind;
  /**
   * Attempts made, including the one that succeeded.
   */
  readonly attempts: number;
  /**
   * Wall-clock duration of the successful attempt.
   */
  readonly duration_ms: number;
}

/**
 * Payload of job.failed.
 */
export interface JobFailedPayload {
  /**
   * Job identity.
   */
  readonly job_id: Identifier;
  /**
   * Work the job attempted.
   */
  readonly kind: JobKind;
  /**
   * Attempts made, including the one that failed.
   */
  readonly attempts: number;
  /**
   * Stable failure class.
   */
  readonly reason: JobFailureReason;
  /**
   * Whether another attempt is scheduled. Stated rather than inferred, so an operator can
   * tell a retry from a dead job without reading the runner's source.
   */
  readonly retrying: boolean;
  /**
   * When the next attempt becomes claimable. Absent when no attempt will follow.
   */
  readonly next_attempt_at?: Timestamp;
}

/**
 * Subscription request (docs/API.md section 18.1).
 */
export interface StreamSubscribe {
  /**
   * Message discriminator.
   */
  readonly type: StreamSubscribeType;
  /**
   * The highest project sequence the client has already applied. Zero means the client
   * holds nothing and wants the stream from its start; a client that has just loaded
   * current state sends the sequence that state was read at.
   */
  readonly last_sequence: number;
  /**
   * Largest replay the client will accept. A gap larger than this is answered with a
   * refresh instruction rather than a long replay, which is cheaper for both sides than
   * paging through history the client is about to refetch anyway.
   */
  readonly max_replay?: number;
}

/**
 * Subscription accepted.
 */
export interface StreamSubscribed {
  /**
   * Message discriminator.
   */
  readonly type: StreamSubscribedType;
  /**
   * Project the stream belongs to.
   */
  readonly project_id: Identifier;
  /**
   * Sequence the stream is at now. Zero when the project has no events yet.
   */
  readonly current_sequence: number;
  /**
   * Oldest sequence still replayable. A client below it receives a refresh instruction
   * instead of a replay.
   */
  readonly earliest_available_sequence: number;
  /**
   * Whether events between the client's position and current_sequence follow before live
   * delivery begins.
   */
  readonly replaying: boolean;
}

/**
 * The client's position cannot be served from the retained stream (docs/EVENTS.md section
 * 10).
 */
export interface StreamRefreshRequired {
  /**
   * Message discriminator.
   */
  readonly type: StreamRefreshRequiredType;
  /**
   * Why a replay was not possible.
   */
  readonly reason: StreamRefreshRequiredReason;
  /**
   * Sequence the stream is at now. A client refetches state and resumes from it.
   */
  readonly current_sequence: number;
  /**
   * Oldest sequence still replayable.
   */
  readonly earliest_available_sequence: number;
}

/**
 * Liveness on a quiet stream.
 */
export interface StreamHeartbeat {
  /**
   * Message discriminator.
   */
  readonly type: StreamHeartbeatType;
  /**
   * Sequence the stream is at now.
   */
  readonly current_sequence: number;
  /**
   * When the control plane sent the heartbeat.
   */
  readonly sent_at: Timestamp;
}

/**
 * A refusal on an open subscription.
 */
export interface StreamError {
  /**
   * Message discriminator.
   */
  readonly type: StreamErrorType;
  /**
   * Stable error code.
   */
  readonly code: ErrorClass;
  /**
   * Human-readable explanation. It never carries request data, a credential or a stack
   * trace.
   */
  readonly message: string;
  /**
   * Whether repeating the subscription verbatim can succeed. Stated rather than inferred
   * from the code, because the answer is not derivable from the code's shape.
   */
  readonly retryable: boolean;
}

/**
 * Code-specific refusal detail (docs/MCP_SPEC.md section 12). Every member is optional and
 * the object refuses unknown members, so the detail a caller may rely on is a fixed
 * vocabulary rather than whatever a handler happened to attach.
 */
export interface ApiErrorDetails {
  /**
   * The version the record actually holds. Carried by VERSION_CONFLICT so a caller can
   * re-read and retry rather than guess.
   */
  readonly current_version?: number;
  /**
   * The version the caller supplied. Carried beside current_version so a log line records
   * both halves of the conflict without the caller having to quote its own request back.
   */
  readonly expected_version?: number;
  /**
   * The control epoch that is current. Carried by CONTROL_EPOCH_STALE.
   */
  readonly current_epoch?: number;
  /**
   * Identifiers the caller may name to resolve the ambiguity. Carried by
   * PROJECT_CONTEXT_AMBIGUOUS.
   */
  readonly candidates?: readonly Identifier[];
  /**
   * Transitions that are legal from the record's current state. Carried by a refused
   * transition.
   */
  readonly allowed_transitions?: readonly string[];
  /**
   * Evidence the operation needs before it can succeed. Carried by EVIDENCE_REQUIRED.
   */
  readonly required_evidence?: readonly string[];
  /**
   * Captured context the request omitted. Carried by a refusal to store a finding that
   * could not be reproduced later.
   */
  readonly missing_context?: readonly string[];
  /**
   * How long to wait before repeating the request. Carried by RATE_LIMITED and by a
   * duplicate that arrived while the first call was still in flight.
   */
  readonly retry_after_ms?: number;
  /**
   * The request member the refusal is about.
   */
  readonly field?: string;
  /**
   * Stable sub-reason where one code covers several causes.
   */
  readonly reason?: string;
}

/**
 * The refusal itself (docs/API.md section 5).
 */
export interface ApiError {
  /**
   * Stable machine-readable code.
   */
  readonly code: ErrorClass;
  /**
   * Human-readable explanation. It never carries a credential, request data or a stack
   * trace (docs/SECURITY.md section 18).
   */
  readonly message: string;
  /**
   * Code-specific detail.
   */
  readonly details?: ApiErrorDetails;
}

/**
 * Response metadata carried by every API response (docs/API.md sections 5 and 6).
 */
export interface ApiMeta {
  /**
   * Correlation identifier for this request, conventionally prefixed req_. It appears on
   * success and on refusal, so a caller can quote one identifier when reporting either.
   */
  readonly request_id: Identifier;
  /**
   * Cursor for the next page. Absent on the last page and on a response that is not a
   * collection.
   */
  readonly next_cursor?: Cursor;
}

/**
 * The complete refusal body (docs/API.md section 5). A success body is {"data": ...,
 * "meta": ...} whose data is endpoint-specific and therefore defined by the endpoint's own
 * schema; meta is api_meta in both cases.
 */
export interface ApiErrorResponse {
  /**
   * The refusal.
   */
  readonly error: ApiError;
  /**
   * Response metadata.
   */
  readonly meta: ApiMeta;
}

/**
 * What an opaque pagination cursor encodes. It is defined here so both languages encode
 * and decode the same bytes, and never to invite a client to build one: the encoded form
 * is base64url text and the API refuses a cursor whose shape it did not produce.
 */
export interface CursorClaims {
  /**
   * Cursor format version. A cursor of another version is refused rather than guessed at.
   */
  readonly version: number;
  /**
   * Value of the collection's sort column at the last row of the previous page.
   */
  readonly sort_key: string;
  /**
   * Identifier of the last row of the previous page, which breaks ties when the sort
   * column repeats.
   */
  readonly id: Identifier;
}

/**
 * A decoded control frame: envelope header plus the payload selected by its type.
 */
export type PlatformFrame =
  | {
      readonly envelope: Envelope;
      readonly type: "organisation.created";
      readonly payload: OrganisationCreatedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "project.created";
      readonly payload: ProjectCreatedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "project.updated";
      readonly payload: ProjectUpdatedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "project.repository_changed";
      readonly payload: ProjectRepositoryChangedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "project.archived";
      readonly payload: ProjectArchivedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "user.invited";
      readonly payload: UserInvitedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "user.credentials_set";
      readonly payload: UserCredentialsSetPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "authentication.login_succeeded";
      readonly payload: AuthenticationLoginSucceededPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "authentication.login_failed";
      readonly payload: AuthenticationLoginFailedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "session.revoked";
      readonly payload: SessionRevokedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "connector.enrolled";
      readonly payload: ConnectorEnrolledPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "connector.connected";
      readonly payload: ConnectorConnectedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "connector.degraded";
      readonly payload: ConnectorDegradedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "connector.disconnected";
      readonly payload: ConnectorDisconnectedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "connector.revoked";
      readonly payload: ConnectorRevokedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "workspace.observed";
      readonly payload: WorkspaceObservedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "workspace.head_changed";
      readonly payload: WorkspaceHeadChangedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "job.enqueued";
      readonly payload: JobEnqueuedPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "job.succeeded";
      readonly payload: JobSucceededPayload;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "job.failed";
      readonly payload: JobFailedPayload;
    }
;
